    "A61M5/00": {
      "code": "A61M5/00",
      "level": 7,
      "parent": null,
      "ja": "皮下，静脈内，筋肉内から，人体内に媒体を導入する用具；そのための補助具，例．充填，支持，または洗浄するための用具，肘掛け（獣医用のワクチン接種用器具Ａ６１Ｄ１／０２５；医療用に特に適合させた管接合具，管継手，弁または分岐器具Ａ６１Ｍ３９／００；医療または製剤のために特に適合させた容器Ａ６１Ｊ１／００；中身を混ぜるまたは移すためのバイアル瓶と注射器が結合したものＡ６１Ｊ１／２０；血液または医療用流体を採取，保存または投与するための容器の保持具Ａ６１Ｊ１／１６）",
      "en": "Devices for bringing media into the body in a subcutaneous, intra-vascular or intramuscular way; Accessories therefor, e.g. filling or cleaning devices, arm-rests ({vaccination appliances for veterinary use A61D1/025} ; tube connectors, tube couplings, valves or branch units specially adapted for medical use A61M39/00; containers specially adapted for medical or pharmaceutical purposes A61J1/00; {combinations of vial and syringe for mixing or transferring their contents A61J1/20; holders for containers for collecting, storing or administering blood or medical fluids A61J1/16})",
      "count": 1297,
      "ipcCode": "A61M5/00",
      "coreCode": "A61M5/00",
      "note": "",
      "sourceFile": "cpc_A61M.txt",
      "kind": "cpc"
    },
