      "ja": "睡眠または弛緩を誘発するためのもの，例．直接的神経刺激，催眠，無痛法によるもの（マッサージのためのものＡ６１Ｈ；電気治療Ａ６１Ｎ，例．麻酔を導入するため交流または間欠電流を適用するものＡ６１Ｎ１／３４(ＥＣＬＡ)）",
      "en": "for inducing sleep or relaxation, e.g. by direct nerve stimulation, hypnosis, analgesia (for massage A61H; electrotherapy A61N, e.g. applying alternating or intermittent electric currents for producing anaesthesia A61N1/36021)",
