      "en": "Catheters; Hollow probes (dilators A61M29/00; {peritoneal catheters A61M1/285; tracheal tubes A61M16/04; for drainage A61M27/00; for uterus, vagina or rectum A61M31/00} ; for measuring or testing A61B; {materials for catheters A61L29/00})",
