    "A61M2202/04": {
      "code": "A61M2202/04",
      "level": 8,
      "parent": "A61M2202/00",
      "ja": "液体<br>注．<br>符号には付加的な符号が続くこともある．記号は下記にあげた意味を持つ．<br>　＋Ａはフィルターに入る流体；<br>　＋Ｂはフィルターエレメントを通過せずにクロスフローフィルターから出て行く流体；<br>　＋Ｃはろ過液，すなわちフィルターを通過する流体；<br>　＋Ｄはその大きさのために保持された残留物；<br>　＋Ｅは吸着作用によって保持されたもの；<br>　＋Ｆは生物学的作用により変化されるもの<br>　＋Ｈは保持されるまたは採取される生成物，例．成分除去によるもの；<br>　＋Ｋは化学作用によって変化させられるもの；<br>　＋Ｗは洗い流される生成物；<br>　＋Ｚは遠心分離によって創出される最初の生成物。",
      "en": "Liquids",
      "count": 812,
      "ipcCode": "CPCONLY",
      "coreCode": "A61M2202/04",
      "note": "",
      "sourceFile": "cpc_A61M.txt",
      "kind": "cpc"
    },
